def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    unprov = 0
    recent_len = 10
    recent_d = 0
    recent_c = 0

    for i in range(n):
        me, op = history[i]
        if op == 'D':
            opp_d += 1
        if me == 'D':
            my_d += 1

        if i >= n - recent_len:
            if op == 'D':
                recent_d += 1
            else:
                recent_c += 1

        if i == 0:
            if op == 'D':
                unprov += 1
        else:
            if op == 'D' and history[i - 1][0] == 'C':
                unprov += 1

    last_me, last_opp = history[-1]

    opp_run = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            opp_run += 1
        else:
            break

    if opp_d == n:
        return 'D'

    if n >= 6 and recent_d >= min(10, n):
        return 'D'

    if opp_d == 0:
        if n >= 12:
            return 'D'
        return 'C'

    if last_opp == 'C':
        if unprov >= 4 and (recent_d >= 4 or opp_d * 5 >= n * 2):
            return 'D'

        if recent_c >= 7 and unprov >= 3 and opp_d <= max(4, n // 5):
            return 'D'

        if last_me == 'D' and recent_c >= 5 and unprov >= 2 and opp_d <= max(4, n // 5):
            return 'D'

        if my_d > opp_d + 2 and opp_d < n // 2:
            return 'C'

        return 'C'

    if n >= 2 and history[-2][0] == 'D':
        if recent_c > 0 and opp_d <= max(4, n // 2):
            return 'C'
        return 'D'

    if last_me == 'D':
        if recent_c > 0 and opp_d <= max(3, n // 2):
            return 'C'
        return 'D'

    if unprov >= 4 or opp_d * 2 >= n:
        return 'D'

    if opp_run >= 3 and recent_c > 0 and opp_d <= max(4, n // 2):
        return 'C'

    if my_d > opp_d + 2 and opp_d < n // 2:
        return 'C'

    return 'D'
